-- ============================================================
--  SEED — dados reais (Iguá + Barra do Piraí / Bairro de Fátima)
--  Rode DEPOIS do supabase_completo.sql.
--  Seguro rodar mais de uma vez (evita duplicar via NOT EXISTS).
-- ============================================================

do $$
declare
  v_bp uuid;
  v_igua uuid;
begin
  -- Iguá (recomposição, sem mapa)
  select id into v_igua from contratos where numero='4600007952' limit 1;
  if v_igua is null then
    values ('4600007952','RECOMPOSIÇÃO IGUÁ','RECOMPOSIÇÃO ASFÁLTICA E NÃO ASFÁLTICA','recomposicao','Iguá',false)
    returning id into v_igua;
  end if;
  -- Barra do Piraí (drenagem/pavimentação, com mapa)
  select id into v_bp from contratos where numero='014/2025' limit 1;
  if v_bp is null then
    values ('014/2025','BARRA DO PIRAÍ — BAIRRO DE FÁTIMA','DRENAGEM E PAVIMENTAÇÃO','tubos','SEIOP','Bairro de Fátima',true,-22.4748034,-44.0489667)
    returning id into v_bp;
  end if;
  delete from drenagem_trechos where contrato_id=v_bp;
  delete from pavimentacao_trechos where contrato_id=v_bp;
  delete from avanco_servicos where contrato_id=v_bp;
  -- Drenagem: trechos PV->PV
  -- Drenagem: ralos
  -- Pavimentação: segmentos
  -- Avanço por serviço (da medição)
end $$;

